        // Number of warps = blockDim.x / 32
        int num_warps = blockDim.x / 32;
        float w_max = (lane < num_warps) ? shared_max[lane] : -INFINITY;
        float w_sum = (lane < num_warps) ? shared_sum[lane] : 0.0f;

        warp_reduce(w_max, w_sum);

        if (lane == 0) {
            shared_max[0] = w_max;
            shared_sum[0] = w_sum;
